import {createClient} from '@supabase/supabase-js';
import {id,clone,initialState,sampleTemplate,execute,clockAt,roundAt,financials,prizes,statsFor,paymentTotal,tablesRequired,tablesInUse,upgradeState,normalizePlayerName,rebuyOpen,rebuyPhase,cutoffHasBreak} from './domain.mjs';
import {SUPABASE_URL,SUPABASE_KEY} from './config.mjs';

const db=createClient(SUPABASE_URL,SUPABASE_KEY);
const APP_ROOT=new URL('.',location.href).pathname;
const $=q=>document.querySelector(q), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n/100);
const tvMoney=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:n%100?2:0,maximumFractionDigits:2}).format(n/100);
const num=n=>Number(n||0).toLocaleString('en-US');
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const app=$('#app'),dlg=$('#dialog');
const localKey='uno-tournament-practice-v1';
let state=loadPractice(),version=0,session=null,mode='practice',busy=false,channel=null,online=false,serverSample=null,lastSync=null,remoteError='',clockTimer,editor=null;
let selected=localStorage.getItem('uno-tournament-selected')||'',view=new URLSearchParams(location.search).get('view')||'home';
const requestedTournament=new URLSearchParams(location.search).get('tournament');if(requestedTournament)selected=requestedTournament;
let playerSearch='',signupSearch='',playerDetail=null,showArchived=false,tab='players',lastClockKey='',sound=false;
const icons={setup:'<path d="m9 3-1 3-3 1-2 3 2 2-1 3 3 2 3-1 2 2 3-1 1-3 3-1 2-3-2-2 1-3-3-2-3 1-2-2Z"/><circle cx="12" cy="12" r="3"/>',players:'<circle cx="12" cy="7" r="3"/><path d="M6 21v-3a6 6 0 0 1 12 0v3M3 8a2 2 0 0 0 0 4m18-4a2 2 0 0 1 0 4M1 20v-2a4 4 0 0 1 4-4m18 6v-2a4 4 0 0 0-4-4"/>',signup:'<path d="M14 3H4v18h11M14 3l5 5v5M14 3v5h5M8 8h3m-3 5h5m-5 4h3"/><circle cx="18" cy="18" r="4"/><path d="M18 16v4m-2-2h4"/>',clock:'<rect x="2" y="3" width="20" height="14" rx="1"/><path d="M12 17v4m-5 0h10"/>',manage:'<path d="M7 3h10v7a5 5 0 0 1-10 0ZM7 5H3v3a4 4 0 0 0 4 4m10-7h4v3a4 4 0 0 1-4 4m-5 3v5m-4 1h8"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${icons[k]||icons.clock}</svg>`;
const names={home:'Home',setup:'Tournament Setup',players:'Player Database',signup:'Tournament Registration',manage:'Tournament Management',clock:'Clock Display'};
const current=()=>state.tournaments.find(t=>t.id===selected);
const pName=e=>state.players.find(p=>p.id===e.playerId)?.name||'Archived player';
const active=t=>t.entries.filter(e=>!e.eliminatedAt);
const timeNow=()=>serverSample?serverSample.epoch+(performance.now()-serverSample.mono):Date.now();
function loadPractice(){try{const value=JSON.parse(localStorage.getItem(localKey));if(value?.schemaVersion===1)return upgradeState(value);}catch{}return initialState();}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=error?'show error':'show';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',5000);}
function chooseTournament(value){selected=value;localStorage.setItem('uno-tournament-selected',value);editor=null;render();}
function go(next){view=next;editor=null;playerDetail=null;history.pushState({},'',`${APP_ROOT}?view=${encodeURIComponent(next)}${selected?'&tournament='+encodeURIComponent(selected):''}`);render();}
function dateLabel(value){return new Date(value+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});}
function statusLabel(t){if(t.status==='completed')return 'Completed';return {ready:'Ready to start',running:'In progress',paused:'Paused',ended:'Clock finished'}[clockAt(t,timeNow()).status];}
function header(){const showContext=!['home','players'].includes(view);return `<header class="header"><a class="brand" href="${APP_ROOT}?view=home" data-go="home"><span>UNO CLUB<small>TOURNAMENT DIRECTOR</small></span></a><div class="header-right"><button class="text-button home-link" data-go="home">Home</button><button class="connection" data-action="account"><i class="dot ${mode==='cloud'?(online?'green':'red'):'gold'}"></i>${mode==='cloud'?(online?'Connected':'Reconnect'):'Practice · Sign in'}</button></div></header>${showContext?`<div class="context"><div><span class="eyebrow">TOURNAMENT</span><select id="current-tournament" aria-label="Current tournament"><option value="">Select a tournament</option>${state.tournaments.slice().reverse().map(t=>`<option value="${t.id}" ${t.id===selected?'selected':''}>${esc(t.name)}${t.status==='completed'?' · Completed':''}</option>`).join('')}</select></div><div class="context-actions"><button class="text-button" data-go="home">Main menu</button><button class="button small dark" data-action="open-clock">${icon('clock')} Open clock window</button></div></div>`:''}${mode==='cloud'&&!online?`<div class="mode-note warning">${esc(remoteError||'Connection interrupted. Reconnect to save changes.')} <button data-action="refresh">Retry</button></div>`:''}`;}

function nav(){return `<nav class="nav" aria-label="Tournament pages">${['home','setup','players','signup','manage'].map(k=>`<button class="${view===k?'active':''}" data-go="${k}">${k==='home'?'Overview':icon(k)}<span>${names[k]}</span></button>`).join('')}</nav>`;}
function pageHeading(kicker,title,description='',extra=''){return `<div class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1>${description?`<p class="muted">${description}</p>`:''}</div>${extra}</div>`;}
function empty(title,text,button=''){return `<div class="empty"><span class="empty-icon">${icon('clock')}</span><h2>${title}</h2><p>${text}</p>${button}</div>`;}
function metrics(t){const f=financials(t);return `<div class="metrics"><div><span>Players remaining</span><strong>${active(t).length}<small> / ${t.entries.length}</small></strong></div><div><span>Paid prize pool</span><strong>${money(f.pool)}</strong></div><div><span>Rebuys</span><strong>${f.rebuyCount}</strong></div><div><span>Clock status</span><strong class="status-value" id="status-metric">${statusLabel(t)}</strong></div></div>`;}
function homeTournament(){const isActive=t=>t.status!=='completed'&&(t.entries.length>0||t.startedAt);return (current()&&isActive(current())?current():state.tournaments.slice().reverse().find(isActive));}
function home(){const t=homeTournament();return `${t?`<section class="home-tournament" aria-label="Current tournament"><div><span class="eyebrow">CURRENT TOURNAMENT</span><h2>${esc(t.name)}</h2></div><span class="pill light">${t.startedAt?esc(statusLabel(t)):'Registration open'}</span><span>${t.entries.length} registered players</span><span>${money(t.settings.buyIn)} buy-in</span><button class="button secondary small" data-resume="${t.id}">Open tournament</button></section>`:''}<div class="menu-grid home-menu">${[['setup','Tournament Setup','Create tournaments and edit structures'],['players','Player Database','Add, find, and edit player records'],['signup','Tournament Registration','Enter players into a tournament'],['manage','Tournament Management','Control the clock, rebuys, and eliminations'],['clock','Open Clock Display','Open the TV display in a separate window']].map(([k,title,desc])=>`<button class="menu-card ${k==='clock'?'clock-menu-card':''}" ${k==='clock'?'data-action="open-clock"':`data-go="${k}"`}>${icon(k)}<h3>${title}</h3><p>${desc}</p></button>`).join('')}</div>`;}

function settingsFields(s){const number=(label,key,value,{moneyInput=false,min=0,max}={})=>`<label>${label}<div class="input-wrap">${moneyInput?'<span>$</span>':''}<input type="number" name="${key}" value="${moneyInput?(value/100).toFixed(2):value}" min="${min}" ${max?'max="'+max+'"':''} step="${moneyInput?'0.01':'1'}" required ${moneyInput?'data-money="true"':''}></div></label>`;
  return `<div class="form-section"><h3>Play & seating</h3><div class="form-grid"><label>Starting chips<input type="text" inputmode="numeric" name="startingStack" data-chips="true" value="${num(s.startingStack)}" pattern="[0-9][0-9,]*" autocomplete="off" spellcheck="false" required></label><label>Antes<select name="anteMode"><option value="off" ${s.anteMode==='off'?'selected':''}>Off — keep amounts in structure</option><option value="big_blind" ${s.anteMode==='big_blind'?'selected':''}>Big blind ante</option><option value="per_player" ${s.anteMode==='per_player'?'selected':''}>Each player antes</option></select></label>${number('Seats per table','seatsPerTable',s.seatsPerTable,{min:2,max:12})}</div><p class="muted">Table count is automatic: players ÷ seats per table, rounded up. Occupied tables remain available until you move their players.</p><label class="check"><input type="checkbox" name="pauseBreaks" ${s.pauseBreaks?'checked':''}>Pause at the beginning and end of breaks</label></div><div class="form-section"><h3>Buy-in</h3><p class="muted">Enter the full price the player pays. The dealer toke is included in that price.</p><div class="form-grid">${number('Full buy-in amount','buyIn',s.buyIn,{moneyInput:true})}${number('Dealer toke per buy-in','dealerToke',s.dealerToke,{moneyInput:true})}</div><p class="split-note" id="entry-split">${money(s.buyIn)} total − ${money(s.dealerToke)} dealer toke = ${money(s.buyIn-s.dealerToke)} before the house percentage.</p></div><div class="form-section"><h3>Rebuys</h3><label class="check"><input type="checkbox" name="rebuyEnabled" ${s.rebuyEnabled?'checked':''}>Allow rebuys for players still in the tournament</label><div class="form-grid">${number('Full rebuy amount','rebuyAmount',s.rebuyAmount,{moneyInput:true})}${number('Chips per rebuy','rebuyChips',s.rebuyChips)}${number('Last round before rebuys end','rebuyLastRound',s.rebuyLastRound)}${number('Maximum per player (0 = unlimited)','rebuyMax',s.rebuyMax)}</div><p class="muted">No dealer toke is taken from rebuys. If a break immediately follows the last rebuy round, rebuys remain open through that break.</p></div><div class="form-section"><h3>Add-ons</h3><label class="check"><input type="checkbox" name="addonEnabled" ${s.addonEnabled?'checked':''}>Allow one add-on per player</label><div class="form-grid">${number('Full add-on amount','addonAmount',s.addonAmount,{moneyInput:true})}${number('Chips per add-on','addonChips',s.addonChips)}${number('Last round before add-on ends','addonLastRound',s.addonLastRound)}</div><p class="muted">If a break immediately follows the last add-on round, add-ons remain available through that break.</p></div><div class="form-section"><h3>House fee at settlement</h3><div class="form-grid">${number('House percentage','housePercent',s.housePercent,{max:100})}${number('House contribution added to prizes','houseContribution',s.houseContribution,{moneyInput:true})}</div><p class="muted">The house percentage is calculated on paid buy-ins after dealer tokes, plus paid rebuys and enabled add-ons. It is settled when you finish the tournament; prize estimates reserve it as payments arrive.</p></div>`;}
function readSettings(form,base){const s=clone(base),f=new FormData(form);for(const el of form.querySelectorAll('input[name],select[name]')){if(!(el.name in s))continue;if(el.type==='checkbox')s[el.name]=el.checked;else if(el.dataset.chips)s[el.name]=Number(el.value.replace(/,/g,''));else if(el.dataset.money)s[el.name]=Math.round(Number(el.value)*100);else if(el.type==='number')s[el.name]=Number(el.value);else s[el.name]=el.value;}return s;}
function levelRows(levels){let round=0,br=0;return levels.map((l,i)=>`<tr data-level="${i}"><td class="level-title">${l.kind==='break'?'Break '+ ++br:'Round '+ ++round}<input type="hidden" name="kind" value="${l.kind}"></td><td><input aria-label="${l.kind} duration in minutes" type="number" name="minutes" min="${l.kind==='break'?1:0.1}" max="180" step="${l.kind==='break'?1:0.1}" required value="${l.minutes}"></td><td><input aria-label="Small blind" name="sb" type="number" min="0" step="1" value="${l.sb}" ${l.kind==='break'?'disabled':''}></td><td><input aria-label="Big blind" name="bb" type="number" min="0" step="1" value="${l.bb}" ${l.kind==='break'?'disabled':''}></td><td><input aria-label="Ante amount" name="ante" type="number" min="0" step="1" value="${l.ante}" ${l.kind==='break'?'disabled':''}></td><td><input aria-label="Game name" name="game" maxlength="100" value="${esc(l.game)}" ${l.kind==='break'?'disabled':''}></td><td><input aria-label="Chip-up reminder" name="chipUp" type="checkbox" ${l.chipUp?'checked':''}></td><td class="row-buttons"><button type="button" class="icon-button" data-level-up="${i}" aria-label="Move level up">↑</button><button type="button" class="icon-button" data-level-down="${i}" aria-label="Move level down">↓</button><button type="button" class="icon-button danger-text" data-level-delete="${i}" aria-label="Delete level">×</button></td></tr>`).join('');}
function readLevels(form){return [...form.querySelectorAll('[data-level]')].map(row=>{const get=n=>row.querySelector(`[name="${n}"]`);return {kind:get('kind').value,minutes:Number(get('minutes').value),sb:Number(get('sb').value),bb:Number(get('bb').value),ante:Number(get('ante').value),game:get('game').value,chipUp:get('chipUp').checked};});}
function setup(){if(editor){const e=editor.value;return `${pageHeading(editor.event?'THIS TOURNAMENT ONLY':'REUSABLE STRUCTURE',editor.event?'Tournament settings':editor.isNew?'New structure':'Edit structure',editor.event?'Changes affect this tournament. Your saved structure stays as it was.':'Save different formats and choose one when you create a tournament.','<button class="button secondary" data-action="close-editor">Cancel</button>')}<form id="structure-form" class="panel"><label>Structure name<input name="structureName" value="${esc(e.name)}" required maxlength="100" ${editor.event?'disabled':''}></label>${settingsFields(e.settings)}${!editor.event||current()?.clock.status==='ready'?`<div class="form-section"><div class="section-label"><h3>Levels & breaks</h3><div class="button-row"><button type="button" class="button small secondary" data-action="add-level">+ Playing level</button><button type="button" class="button small secondary" data-action="add-break">+ Break</button></div></div><p class="muted">Durations are minutes from the actual start. Break lengths use whole minutes. Ante amounts remain saved when antes are off.</p><div class="game-copy-row"><label>Game for all playing levels<input id="all-levels-game" value="${esc(e.levels.find(l=>l.kind==='play')?.game||'')}" maxlength="100" placeholder="For example, No Limit Hold’em"></label><button type="button" class="button secondary" data-action="copy-game">Copy game to all levels</button></div><p class="muted small-copy">Use this for a single-game tournament, or edit individual game names below for a mixed tournament.</p><div class="table-scroll"><table class="level-table"><thead><tr><th>Level</th><th>Minutes</th><th>Small blind</th><th>Big blind</th><th>Ante</th><th>Game</th><th>Chip up</th><th>Order</th></tr></thead><tbody>${levelRows(e.levels)}</tbody></table></div></div>`:''}<div class="form-section"><h3>Default payouts</h3><p class="muted">You can change these during a tournament from Tournament Management.</p>${payoutFields(e.settings)}</div><div class="sticky-save"><button class="button primary" type="submit">${editor.event?'Save tournament settings':'Save structure'}</button><button class="button secondary" type="button" data-action="close-editor">Cancel</button></div></form>`;}
return `${pageHeading('MAKE IT YOUR GAME','Tournament Setup','Reusable structures, individual tournaments, and room for a different format every week.','<button class="button primary" data-action="new-tournament">+ New tournament</button>')}${current()?`<div class="panel current-panel"><div><span class="eyebrow">SELECTED TOURNAMENT</span><h2>${esc(current().name)}</h2><p class="muted">${esc(current().templateName)} · Antes ${current().settings.anteMode==='off'?'off':current().settings.anteMode.replace('_',' ')}</p></div><button class="button secondary" data-action="event-settings" ${current().status==='completed'?'disabled':''}>Edit this tournament</button></div>`:''}<div class="section-label"><h2>Saved structures</h2><button class="text-button" data-action="new-structure">+ Create structure</button></div><div class="structure-grid">${state.templates.map(s=>`<article class="panel structure-card"><span class="eyebrow">SAVED STRUCTURE</span><h2>${esc(s.name)}</h2><p>${s.levels.filter(l=>l.kind==='play').length} playing rounds · ${s.levels.filter(l=>l.kind==='break').length} breaks</p><div class="structure-facts"><span>Starting chips <strong>${num(s.settings.startingStack)}</strong></span><span>Buy-in <strong>${money(s.settings.buyIn)}</strong></span><span>Antes <strong>${s.settings.anteMode==='off'?'Optional · Off':s.settings.anteMode.replace('_',' ')}</strong></span></div><div class="button-row"><button class="button primary small" data-create-template="${s.id}">Use structure</button><button class="button secondary small" data-edit-template="${s.id}">Edit</button><button class="text-button" data-copy-template="${s.id}">Duplicate</button><button class="text-button danger-text" data-delete-template="${s.id}">Delete</button></div></article>`).join('')}</div>`;}
function payoutFields(s){return `<div class="form-grid"><label>Prize format<select name="payoutMode" id="payout-mode"><option value="percent" ${s.payoutMode==='percent'?'selected':''}>Percent of paid prize pool</option><option value="fixed" ${s.payoutMode==='fixed'?'selected':''}>Fixed dollar amounts</option></select></label><label>Amounts in finishing order<input name="payoutValues" value="${esc(s.payouts.map(v=>s.payoutMode==='fixed'?(v/100).toFixed(2):v).join(', '))}" required><small>Separate places with commas. Percentages must total 100; fixed amounts are dollars.</small></label></div>`;}
function readPayout(form,s){const fd=new FormData(form);s.payoutMode=fd.get('payoutMode');s.payouts=String(fd.get('payoutValues')).split(',').map(v=>Number(v.trim())*(s.payoutMode==='fixed'?100:1)).map(v=>s.payoutMode==='fixed'?Math.round(v):v);return s;}
function players(){const rows=state.players.filter(p=>(showArchived||!p.archived)&&(normalizePlayerName(p.name)+' '+p.id.toLowerCase()+' '+(p.phone||'')).includes(normalizePlayerName(playerSearch))).sort((a,b)=>a.name.localeCompare(b.name));if(playerDetail){const p=state.players.find(p=>p.id===playerDetail);if(!p){playerDetail=null;return players();}const st=statsFor(state,p.id);return `${pageHeading('PLAYER PROFILE',esc(p.name),'Results reflect completed tournaments.','<button class="button secondary" data-action="players-back">Back to players</button>')}<div class="metrics"><div><span>Tournaments</span><strong>${st.played}</strong></div><div><span>Wins</span><strong>${st.wins}</strong></div><div><span>Cashes</span><strong>${st.cashes}</strong></div><div><span>Winnings</span><strong>${money(st.winnings)}</strong></div></div><div class="two-col"><form id="player-form" class="panel"><h2>Player details</h2><input type="hidden" name="id" value="${p.id}"><label>Player name<input name="name" value="${esc(p.name)}" required maxlength="100" autocomplete="off"></label><label>Player ID<input value="${esc(p.id)}" readonly aria-readonly="true"></label><label>Phone number (optional)<input type="tel" name="phone" value="${esc(p.phone)}" maxlength="40" autocomplete="tel"></label><label>Notes<textarea name="notes" maxlength="1000">${esc(p.notes)}</textarea></label><div class="button-row"><button class="button primary">Save changes</button><button type="button" class="button secondary" data-archive="${p.id}">${p.archived?'Restore player':'Archive player'}</button></div></form><section class="panel"><h2>Tournament history</h2><p class="muted">Recorded costs: ${money(st.cost)} · Net result: ${money(st.winnings-st.cost)}</p>${st.history.length?st.history.map(({t,e})=>`<div class="result-row"><span>${esc(t.name)}<small>${dateLabel(t.date)}</small></span><strong>#${e.place} · ${money(e.winnings)}</strong></div>`).join(''):'<p class="muted">No completed tournaments yet.</p>'}</section></div>`;}
return `${pageHeading('THE PEOPLE AT YOUR TABLES','Player Database','Player names, contact information, and tournament history.','<button class="button primary" data-action="add-player">+ Add player</button>')}<section class="panel"><div class="search-row"><label class="search"><span class="sr-only">Search players</span><input id="player-search" placeholder="Search by name, player ID, or phone…" value="${esc(playerSearch)}" autocomplete="off"></label><label class="check"><input id="show-archived" type="checkbox" ${showArchived?'checked':''}>Show archived</label></div><div id="player-results">${playerRows(rows)}</div></section>`;}
function playerRows(rows){return rows.length?rows.map(p=>`<button class="player-row" data-player="${p.id}"><span class="avatar">${esc(p.name.slice(0,1).toUpperCase())}</span><span><strong>${esc(p.name)}</strong><small>${p.archived?'Archived · ':''}ID: ${esc(p.id)}${p.phone?' · '+esc(p.phone):''}</small></span><span>View player →</span></button>`).join(''):empty(playerSearch?'No matching players':'Your player database is empty',playerSearch?'Try a different name or player ID.':'Add your first player to save their information.','<button class="button primary" data-action="add-player">Add player</button>');}
function noTournament(){return empty('Choose a tournament to continue.','Select one above, or create a tournament from a saved structure.','<button class="button primary" data-action="new-tournament">Create tournament</button>');}
function signup(){const t=current();if(!t)return noTournament();const f=financials(t),enrolled=new Set(t.entries.map(e=>e.playerId));const matches=state.players.filter(p=>!p.archived&&!enrolled.has(p.id)&&p.name.toLowerCase().includes(signupSearch.toLowerCase())).sort((a,b)=>a.name.localeCompare(b.name));return `${pageHeading('WELCOME TO THE TABLE','Tournament Registration',esc(t.name))}${metrics(t)}<div class="two-col signup-layout"><section class="panel"><h2>Register a player</h2><p class="muted">Buy-in ${money(t.settings.buyIn)} · ${num(t.settings.startingStack)} starting chips</p><label>Find a player<input id="signup-search" placeholder="Search any part of the name…" value="${esc(signupSearch)}" autocomplete="off"></label><label class="check"><input id="registration-paid" type="checkbox" checked>Payment received</label><div id="signup-results" class="registration-list">${registrationRows(matches,t)}</div><button class="button secondary full" data-action="add-player">+ Add a new player</button></section><section class="panel"><div class="section-label"><h2>Registered players</h2><span>${t.entries.length} entries</span></div><div class="money-strip"><span>Collected <strong>${money(f.collected)}</strong></span><span>Outstanding <strong>${money(f.owed)}</strong></span></div>${t.entries.length?entryRows(t,false):'<p class="muted">Players appear here as you register them.</p>'}</section></div>`;}
function registrationRows(rows,t){return rows.length?rows.slice(0,80).map(p=>`<button class="register-row" data-register="${p.id}" ${t.status==='completed'?'disabled':''}><span>${esc(p.name)}</span><strong>+ Register</strong></button>`).join(''):'<p class="muted">No matching unregistered players. Add a new player below.</p>';}
function entryRows(t,management){return t.entries.slice().sort((a,b)=>Number(!!a.eliminatedAt)-Number(!!b.eliminatedAt)||pName(a).localeCompare(pName(b))).map(e=>{const paid=e.payments.every(p=>p.paid),rebuys=e.payments.filter(p=>p.kind==='rebuy').length;return `<div class="entry-row ${e.eliminatedAt?'out':''}"><div><strong>${esc(pName(e))}</strong><small>${e.place?'Finished #'+e.place:(e.table?'Table '+e.table+' · Seat '+e.seat:'Not seated')}${rebuys?' · '+rebuys+' rebuy'+(rebuys===1?'':'s'):''} · ${money(e.payments.reduce((a,p)=>a+paymentTotal(p),0))}</small></div><div class="entry-actions">${t.status==='completed'?`<span class="pill light">${money(e.winnings||0)}</span>`:`<button class="pill-button ${paid?'paid':'unpaid'}" data-paid="${e.id}" data-value="${!paid}">${paid?'Paid':'Owes'}</button>${!e.eliminatedAt?`<button class="button tiny secondary" data-rebuy="${e.id}" ${!t.settings.rebuyEnabled?'disabled':''}>Rebuy</button>${t.settings.addonEnabled?`<button class="button tiny secondary" data-addon="${e.id}">Add-on</button>`:''}${management?`<button class="button tiny danger" data-eliminate="${e.id}">Eliminate</button>`:''}`:'<span class="pill light">Eliminated</span>'}`}</div></div>`;}).join('');}
function controls(t){const c=clockAt(t,timeNow());return `<div class="clock-controls"><button class="button primary" id="clock-main" data-clock="${c.status==='running'?'pause':c.status==='ready'?'start':'resume'}" ${c.status==='ended'||t.status==='completed'?'disabled':''}>${c.status==='running'?'Pause clock':c.status==='ready'?'Start tournament':'Resume clock'}</button><button class="button secondary" data-clock="previous" ${c.index===0||t.status==='completed'?'disabled':''}>← Previous level</button><button class="button secondary" data-clock="next" ${c.index===t.levels.length-1||t.status==='completed'?'disabled':''}>Next level →</button><button class="button secondary" data-adjust="-60" ${t.status==='completed'?'disabled':''}>−1 minute</button><button class="button secondary" data-adjust="60" ${t.status==='completed'?'disabled':''}>+1 minute</button></div>`;}
function manage(){const t=current();if(!t)return noTournament();const f=financials(t);return `${pageHeading('RUN THE ROOM','Tournament Management',esc(t.name),'<button class="button secondary" data-action="open-clock">Open TV clock ↗</button>')}${metrics(t)}<section class="panel control-panel"><div class="mini-clock"><span class="eyebrow" id="mini-level"></span><strong id="mini-time">15:00</strong><span id="mini-blinds"></span><small id="mini-note"></small></div><div>${controls(t)}<p class="muted small-copy">Changes apply to this tournament. Remote controls require a cloud connection.</p></div></section><div class="tabs" role="tablist">${[['players','Players'],['tables','Tables & seats'],['payouts','Payouts'],['summary','Financial summary']].map(([k,label])=>`<button role="tab" aria-selected="${tab===k}" data-tab="${k}" class="${tab===k?'active':''}">${label}</button>`).join('')}</div><section class="panel">${tab==='players'?`<div class="section-label"><h2>Players</h2><div class="button-row"><button class="button small secondary" data-action="undo-elimination" ${!t.eliminationUndo.length||t.status==='completed'?'disabled':''}>Undo last elimination</button><button class="button small primary" data-action="finish" ${active(t).length!==1||t.status==='completed'?'disabled':''}>Confirm winner & finish</button></div></div>${t.entries.length?entryRows(t,true):'<p class="muted">Register players from the Sign-Up page.</p>'}`:tab==='tables'?tableManagement(t):tab==='payouts'?`<h2>Prize structure</h2><p class="muted">Current paid prize pool: <strong>${money(f.pool)}</strong>. Percent payouts recalculate as payments are recorded.</p><form id="payout-form">${payoutFields(t.settings)}<button class="button primary" ${t.status==='completed'?'disabled':''}>Save payouts</button></form><div class="prize-preview">${prizes(t).map((v,i)=>`<div><span>${ordinal(i+1)} place</span><strong>${money(v)}</strong></div>`).join('')}</div>`:`<h2>Tournament finances</h2><div class="summary-grid">${[['Collected payments',f.collected],['Outstanding payments',f.owed],['Dealer tokes — buy-ins only',f.dealerTokes],['After dealer tokes, including rebuys',f.houseBase],[f.legacy?'Previously recorded house fees':(t.status==='completed'?'House fee':'House fee reserved for settlement')+' ('+f.housePercent+'%)',f.houseFee],['House contribution',t.settings.houseContribution],['Paid prize pool',f.pool]].map(([label,v])=>`<div><span>${label}</span><strong>${money(v)}</strong></div>`).join('')}</div><p class="muted">Prize pool uses payments marked received, less buy-in dealer tokes and the house percentage. Unpaid amounts are excluded. ${num(f.chips)} chips issued · ${f.rebuyCount} rebuys · ${f.addonCount} add-ons.</p>`}</section>`;}
function tableManagement(t){return `<div class="section-label"><h2>Tables & seats</h2><button class="button secondary small" data-action="auto-seat" ${t.status==='completed'?'disabled':''}>Shuffle & seat remaining players</button></div><p class="muted">${tablesRequired(t)} ${tablesRequired(t)===1?'table':'tables'} needed for ${active(t).length} remaining players · ${t.settings.seatsPerTable} seats per table. ${tablesInUse(t)>tablesRequired(t)?'Occupied tables stay available until players are moved.':'Tables are calculated automatically.'} Assign or move a player using their seat button.</p><div class="seat-tables">${Array.from({length:tablesInUse(t)},(_,i)=>`<div class="seat-table"><h3>Table ${i+1}</h3>${Array.from({length:t.settings.seatsPerTable},(_,j)=>{const e=active(t).find(e=>e.table===i+1&&e.seat===j+1);return `<div><span class="seat-number">${j+1}</span><span>${e?esc(pName(e)):'<span class="muted">Empty</span>'}</span>${e?`<button class="text-button" data-seat="${e.id}">Move</button>`:''}</div>`;}).join('')}</div>`).join('')}</div><h3>Unseated players</h3>${active(t).filter(e=>!e.table).map(e=>`<div class="result-row"><span>${esc(pName(e))}</span><button class="button small secondary" data-seat="${e.id}">Assign seat</button></div>`).join('')||'<p class="muted">All remaining players have seats.</p>'}`;}
function ordinal(n){return n+(n%100>=11&&n%100<=13?'th':({1:'st',2:'nd',3:'rd'})[n%10]||'th');}
function clockSidebar(t,c){
  const phase=rebuyPhase(t,c),open=phase!=='closed',count=active(t).length+' / '+t.entries.length,pool=tvMoney(financials(t).pool),withBreak=cutoffHasBreak(t);
  const notice=phase==='final-round'?`<strong class="tv-final-rebuy">Final Rebuy Round</strong><p class="tv-cutoff-detail">${withBreak?'Rebuys remain open during the following break':'Rebuys close after this round'}</p>`:phase==='final-break'?'<strong>Rebuys Open</strong><p class="tv-cutoff-detail">Rebuys close when this break ends</p>':`<strong>Rebuys Open</strong><p>Through Level ${t.settings.rebuyLastRound}</p>${withBreak?'<p class="tv-cutoff-detail">Includes the following break</p>':''}`;
  return `<div class="tv-players"><span>PLAYERS REMAINING</span><strong style="font-size:min(${open?9:7.5}vw,${52/count.length}vw)">${count}</strong>${!open?`<small class="tv-rebuy-count">Rebuys: ${financials(t).rebuyCount}</small>`:''}</div>${open?`<div class="tv-rebuys-open">${notice}</div>`:`<div class="tv-pool"><span>PRIZE POOL</span><strong style="font-size:min(7.5vw,${52/pool.length}vw)">${pool}</strong></div><div class="tv-prizes"><span>PAYOUTS</span><div class="tv-payout-list">${prizes(t).map((v,i)=>`<p><span>${ordinal(i+1)}</span><strong>${tvMoney(v)}</strong></p>`).join('')}</div></div>`}`;
}

function clockScreen(){const t=current(),c=t?clockAt(t,timeNow()):null;return `<div class="tv-shell"><div class="tv-toolbar"><button data-go="home">← Home</button><span class="tv-mode">${mode==='practice'?'PRACTICE · THIS BROWSER ONLY':online?'CONNECTED':'CONNECTION INTERRUPTED'}</span><button data-action="sound">Sound: ${sound?'on':'off'}</button><button data-action="fullscreen">Full screen ⛶</button></div>${!t?`<div class="tv-empty"><h1>Choose a tournament</h1><p>Open a tournament in the control room, then open its clock display.</p><button class="button gold" data-go="home">Open home screen</button></div>`:`<header class="tv-heading"><div><span>UNO CLUB</span><h1>${esc(t.name)}</h1></div><div id="tv-level">ROUND 1</div></header><main class="tv-grid"><section class="tv-time-panel"><span class="tv-time-label">TIME REMAINING</span><div class="tv-status" id="tv-status"></div><div class="tv-time" id="tv-time">15:00</div><div class="tv-progress"><div id="tv-progress"></div></div><div class="tv-break" id="tv-break"></div></section><section class="tv-blinds-panel"><span id="tv-game">CURRENT BLINDS</span><strong id="tv-blinds">25 / 50</strong><div id="tv-ante">Antes off</div><p class="tv-next-row"><span id="tv-next-label">NEXT BLINDS</span><strong id="tv-next"></strong></p></section><aside class="tv-side ${rebuyOpen(t,c)?'pre-rebuys':'post-rebuys'}" data-rebuy-phase="${rebuyPhase(t,c)}">${clockSidebar(t,c)}</aside></main>`}</div>`;}

function render(){clearInterval(clockTimer);document.body.classList.toggle('tv',view==='clock');document.body.classList.toggle('home-page',view==='home');if(view==='clock'){app.innerHTML=clockScreen();}else{app.innerHTML=header()+`<div class="workspace">${view==='home'?'':nav()}<main class="content">${({home,setup,players,signup,manage}[view]||home)()}</main><footer class="app-footer"><span>UNO CLUB · TOURNAMENT DIRECTOR</span><span>v0.2.3 · ${mode==='cloud'?'Saved to Supabase':'Practice mode'}</span></footer></div>`;}tick();clockTimer=setInterval(tick,250);}
function setText(selector,text){const el=$(selector);if(el&&el.textContent!==String(text))el.textContent=text;}
function formatTime(ms){const sec=Math.max(0,Math.ceil(ms/1000));return `${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`;}
function nextBreak(t,c){if(t.levels[c.index].kind==='break')return 'Break in progress';let ms=c.remainingMs;for(let i=c.index+1;i<t.levels.length;i++){if(t.levels[i].kind==='break')return 'Next break in '+formatTime(ms);ms+=t.levels[i].minutes*60000;}return 'No further breaks scheduled';}
function tick(){const t=current();if(!t)return;const c=clockAt(t,timeNow()),l=t.levels[c.index],round=roundAt(t,c.index);const level=l.kind==='break'?'BREAK':'ROUND '+round,blinds=l.kind==='break'?'Take a break':num(l.sb)+' / '+num(l.bb);const status=t.status==='completed'?'TOURNAMENT COMPLETE':({ready:'READY TO START',running:l.kind==='break'?'BREAK':'LEVEL IN PROGRESS',paused:'CLOCK PAUSED',ended:'SCHEDULE COMPLETE'})[c.status];
  setText('#hero-time',formatTime(c.remainingMs));setText('#hero-blinds',level+' · '+blinds);setText('#mini-level',level);setText('#mini-time',formatTime(c.remainingMs));setText('#mini-blinds',blinds);setText('#mini-note',status);setText('#status-metric',statusLabel(t));
  const side=$('.tv-side');if(side&&side.dataset.rebuyPhase!==rebuyPhase(t,c)){side.dataset.rebuyPhase=rebuyPhase(t,c);side.className='tv-side '+(rebuyOpen(t,c)?'pre-rebuys':'post-rebuys');side.innerHTML=clockSidebar(t,c);}
  setText('#tv-level',level);setText('#tv-status',c.status==='running'?'':status);setText('#tv-time',formatTime(c.remainingMs));setText('#tv-game',l.kind==='break'?(l.chipUp?'BREAK · CHIP UP':'BREAK'):'CURRENT BLINDS');setText('#tv-blinds',blinds);setText('#tv-ante',l.kind==='play'&&t.settings.anteMode!=='off'&&l.ante?'Ante '+num(l.ante)+' · '+(t.settings.anteMode==='big_blind'?'Big blind':'Each player'):'Antes off');setText('#tv-break',nextBreak(t,c));
  const next=t.levels[c.index+1];setText('#tv-next-label',next?.kind==='break'?'NEXT BREAK':'NEXT BLINDS');setText('#tv-next',next?(next.kind==='break'?`${next.minutes} minutes${next.chipUp?' · Chip up':''}`:`${num(next.sb)} / ${num(next.bb)}`):'Final level');
  $('#tv-time')?.classList.toggle('urgent',c.remainingMs<=60000&&c.status==='running');if($('#tv-progress'))$('#tv-progress').style.width=(100*Math.min(1,c.remainingMs/(l.minutes*60000)))+'%';
  const b=$('#clock-main');if(b){const command=c.status==='running'?'pause':c.status==='ready'?'start':'resume';b.dataset.clock=command;b.textContent=c.status==='running'?'Pause clock':c.status==='ready'?'Start tournament':'Resume clock';b.disabled=busy||c.status==='ended'||t.status==='completed';}
  const key=`${t.id}/${c.index}/${c.status}`;if(lastClockKey&&key!==lastClockKey&&view==='clock'&&sound)beep();lastClockKey=key;
  if(view==='clock'&&mode==='cloud') {setText('#tv-footer-status',online?'Live · Connected':remoteError?'Offline · Clock continues; changes not received':'Connecting…');setText('.tv-mode',online?'CLOUD CONNECTED':'CONNECTION INTERRUPTED');}
}
function beep(){try{const C=window.AudioContext||window.webkitAudioContext;const ctx=new C();const o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=660;g.gain.value=.12;o.start();o.stop(ctx.currentTime+.35);o.onended=()=>ctx.close();}catch{}}
async function commit(action){if(busy)return false;busy=true;document.body.classList.add('saving');try{
    if(mode==='cloud'&&!online)throw new Error('Reconnect before making changes. The clock will continue.');
    const next=execute(state,action,timeNow());
    if(mode==='cloud'){
      const {data,error}=await db.rpc('td_save_workspace',{p_expected_version:version,p_state:next});
      if(error){if(error.message.includes('TD_CONFLICT')){await refresh(true);throw new Error('Another device changed the tournament. Review the latest information and try again.');}throw error;}
      const saved=Array.isArray(data)?data[0]:data;if(!saved?.state)throw new Error('Save response was incomplete. Refresh before retrying.');
      state=upgradeState(saved.state);version=Number(saved.version);lastSync=Date.now();online=true;
    }else{state=next;localStorage.setItem(localKey,JSON.stringify(state));}
    render();return true;
  }catch(error){toast(error.message||'Could not save. Please retry.',true);return false;}finally{busy=false;document.body.classList.remove('saving');tick();}}
async function synchronizeTime(){const before=performance.now();const {data,error}=await db.rpc('td_server_time');if(!error)serverSample={epoch:Date.parse(data),mono:(before+performance.now())/2};}
async function refresh(force=false){if(mode!=='cloud'||!session||(busy&&!force))return;try{
    const {data,error}=await db.from('td_workspaces').select('state,version,updated_at').eq('owner_id',session.user.id).maybeSingle();if(error)throw error;
    let changed=false;if(data&&Number(data.version)>version){state=upgradeState(data.state);version=Number(data.version);changed=true;}
    const wasOffline=!online;online=true;remoteError='';lastSync=Date.now();
    if((changed||wasOffline)&&!dlg.open&&!editor&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))render();
  }catch(e){const changed=online;online=false;remoteError=e.message||'Could not reach Supabase.';if(changed&&!dlg.open&&!editor)render();}}
async function enterCloud(){if(channel){await db.removeChannel(channel);channel=null;}mode='cloud';version=0;state=initialState();serverSample=null;online=false;remoteError='Connecting to your saved tournaments…';render();await synchronizeTime();await refresh();channel=db.channel('workspace-'+session.user.id).on('postgres_changes',{event:'*',schema:'public',table:'td_workspaces',filter:'owner_id=eq.'+session.user.id},()=>refresh()).subscribe();render();}
async function enterPractice(){if(channel){await db.removeChannel(channel);channel=null;}mode='practice';state=loadPractice();version=0;serverSample=null;online=false;editor=null;render();}
function modal(title,body){dlg.innerHTML=`<div class="modal-heading"><h2>${title}</h2><button type="button" class="icon-button" data-action="close-modal" aria-label="Close dialog">×</button></div>${body}`;if(!dlg.open)dlg.showModal();}
function showAccount(){modal('Computer & phone access',`<p class="muted">Sign in to the same Tournament Director data account on your computer and phone. Your Supabase dashboard password is separate.</p>${session?`<div class="account-status"><strong>${esc(session.user.email)}</strong><p>${mode==='cloud'?'Using your shared tournament data.':'Currently using practice data.'}</p><button class="button primary" data-action="use-cloud">Use shared tournaments</button><button class="button secondary" data-action="signout">Sign out of data account</button></div>`:`<form id="auth-form"><label>Email<input type="email" name="email" autocomplete="email" required></label><label>Password<input type="password" name="password" autocomplete="current-password" minlength="8" required></label><div class="button-row"><button class="button primary" name="authAction" value="login">Sign in</button><button class="button secondary" name="authAction" value="signup">Create data account</button></div><p id="auth-feedback" class="muted" role="status">For a new account, confirm your email if prompted, then sign in here on each device.</p></form>`}<hr><h3>Try it first</h3><p class="muted">Practice data stays in this browser. It is separate from cloud tournaments and does not sync to your phone.</p><button class="button secondary" data-action="use-practice">Use practice mode</button>`);}
function newTournament(templateId){modal('Create a tournament',`<form id="new-tournament-form"><label>Tournament name<input name="name" placeholder="Wednesday tournament" required maxlength="120"></label><label>Tournament date<input type="date" name="date" value="${today()}" required></label><label>Saved structure<select name="templateId">${state.templates.map(s=>`<option value="${s.id}" ${s.id===templateId?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><p class="muted">This creates an independent copy. You can change its settings without changing the saved structure.</p><button class="button primary full">Create tournament</button></form>`);}
function newPlayer(){modal('Add a player',`<form id="player-form"><label>Player name<input name="name" value="${esc(view==='signup'?signupSearch:'')}" maxlength="100" placeholder="Name or nickname" autocomplete="off" required></label><p class="name-feedback" id="player-name-feedback" role="status"></p><label>Phone number (optional)<input type="tel" name="phone" maxlength="40" autocomplete="tel"></label><label>Notes (optional)<textarea name="notes" maxlength="1000"></textarea></label><button class="button primary full">Save player</button></form>`);}
function editTemplate(templateId,copy=false){const value=clone(state.templates.find(t=>t.id===templateId));if(copy){value.id=id();value.name+=' — copy';}editor={value,isNew:copy,event:false,version};view='setup';render();}
function captureEditor(){const form=$('#structure-form');if(!form)return;editor.value.name=form.elements.structureName.value;editor.value.settings=readPayout(form,readSettings(form,editor.value.settings));if(form.querySelector('[data-level]'))editor.value.levels=readLevels(form);}
function paymentDialog(entryId,kind){const t=current(),e=t.entries.find(e=>e.id===entryId);modal(kind==='rebuy'?'Record rebuy':'Record add-on',`<form id="payment-form"><input type="hidden" name="entryId" value="${entryId}"><input type="hidden" name="kind" value="${kind}"><p><strong>${esc(pName(e))}</strong></p><p>${money(t.settings[kind+'Amount'])} · ${num(t.settings[kind+'Chips'])} chips</p><label class="check"><input name="paid" type="checkbox" checked>Payment received</label><button class="button primary full">Record ${kind==='rebuy'?'rebuy':'add-on'}</button></form>`);}
function seatDialog(entryId){const t=current(),e=t.entries.find(e=>e.id===entryId);modal('Seat '+esc(pName(e)),`<form id="seat-form"><input type="hidden" name="entryId" value="${entryId}"><label>Seat<select name="seat"><option value="unseated">Unseated</option>${Array.from({length:tablesInUse(t)},(_,i)=>Array.from({length:t.settings.seatsPerTable},(_,j)=>{const occupied=active(t).some(v=>v.id!==e.id&&v.table===i+1&&v.seat===j+1);return `<option value="${i+1}/${j+1}" ${e.table===i+1&&e.seat===j+1?'selected':''} ${occupied?'disabled':''}>Table ${i+1}, Seat ${j+1}${occupied?' · occupied':''}</option>`;}).join('')).join('')}</select></label><button class="button primary full">Save seat</button></form>`);}
function openClock(){const target=view==='home'?(homeTournament()||current()):current();if(target&&target.id!==selected){selected=target.id;localStorage.setItem('uno-tournament-selected',selected);}if(!target){toast('Choose or create a tournament first.',true);return;}const url=`${APP_ROOT}?view=clock&tournament=${encodeURIComponent(selected)}`;const win=window.open(url,'uno-clock-'+selected,'popup=yes,width=1280,height=800');if(!win)toast('Allow pop-ups for this site to open the clock window.',true);else win.focus();}

document.addEventListener('click',async event=>{const el=event.target.closest('button,a[data-go]');if(!el||el.disabled)return;try{
  if(el.dataset.go){event.preventDefault();go(el.dataset.go);return;}
  if(el.dataset.resume){chooseTournament(el.dataset.resume);go('signup');return;}
  if(el.dataset.select){chooseTournament(el.dataset.select);return;}
  if(el.dataset.tab){tab=el.dataset.tab;render();return;}
  if(el.dataset.player){playerDetail=el.dataset.player;render();return;}
  if(el.dataset.createTemplate){newTournament(el.dataset.createTemplate);return;}
  if(el.dataset.editTemplate){editTemplate(el.dataset.editTemplate);return;}
  if(el.dataset.copyTemplate){editTemplate(el.dataset.copyTemplate,true);return;}
  if(el.dataset.deleteTemplate){if(confirm('Delete this saved structure? Existing tournaments keep their copies.'))await commit({type:'template-delete',id:el.dataset.deleteTemplate});return;}
  if(el.dataset.register){const paid=$('#registration-paid').checked;if(await commit({type:'register',tournamentId:selected,playerId:el.dataset.register,paid})){signupSearch='';render();toast('Player registered.');}return;}
  if(el.dataset.rebuy){paymentDialog(el.dataset.rebuy,'rebuy');return;}if(el.dataset.addon){paymentDialog(el.dataset.addon,'addon');return;}
  if(el.dataset.paid){await commit({type:'paid',tournamentId:selected,entryId:el.dataset.paid,paid:el.dataset.value==='true'});return;}
  if(el.dataset.eliminate){const e=current().entries.find(e=>e.id===el.dataset.eliminate);if(confirm(`Eliminate ${pName(e)} in ${ordinal(active(current()).length)} place?`))await commit({type:'eliminate',tournamentId:selected,entryId:e.id});return;}
  if(el.dataset.archive){await commit({type:'player-archive',id:el.dataset.archive});return;}
  if(el.dataset.seat){seatDialog(el.dataset.seat);return;}
  if(el.dataset.clock){if(['next','previous'].includes(el.dataset.clock)&&!confirm('Change the current level and reset its countdown?'))return;await commit({type:'clock',tournamentId:selected,command:el.dataset.clock});return;}
  if(el.dataset.adjust){await commit({type:'clock',tournamentId:selected,command:'adjust',seconds:Number(el.dataset.adjust)});return;}
  if(el.dataset.levelDelete!==undefined||el.dataset.levelUp!==undefined||el.dataset.levelDown!==undefined){captureEditor();const l=editor.value.levels;if(el.dataset.levelDelete!==undefined)l.splice(Number(el.dataset.levelDelete),1);else{const i=Number(el.dataset.levelUp??el.dataset.levelDown),j=i+(el.dataset.levelUp!==undefined?-1:1);if(j>=0&&j<l.length)[l[i],l[j]]=[l[j],l[i]];}render();return;}
  switch(el.dataset.action){
    case 'account':showAccount();break;case 'close-modal':dlg.close();break;case 'new-tournament':newTournament();break;case 'add-player':newPlayer();break;
    case 'players-back':playerDetail=null;render();break;case 'open-clock':openClock();break;case 'refresh':await refresh();break;
    case 'use-cloud':dlg.close();if(session)await enterCloud();break;case 'use-practice':dlg.close();await enterPractice();break;
    case 'signout':await db.auth.signOut();session=null;dlg.close();await enterPractice();break;
    case 'new-structure':{const value=sampleTemplate();value.name='New tournament structure';editor={value,isNew:true,event:false,version};view='setup';render();break;}
    case 'event-settings':{const t=current();editor={event:true,version,value:{id:t.id,name:t.name,settings:clone(t.settings),levels:clone(t.levels)}};view='setup';render();break;}
    case 'close-editor':editor=null;render();break;
    case 'copy-game':{const game=$('#all-levels-game').value.trim();if(!game){toast('Enter a game name to copy.',true);break;}for(const row of $('#structure-form').querySelectorAll('[data-level]')){if(row.querySelector('[name=kind]').value==='play')row.querySelector('[name=game]').value=game;}captureEditor();toast('Game copied to all playing levels. Save the structure to keep it.');break;}
    case 'add-level':case 'add-break':captureEditor();editor.value.levels.push({kind:el.dataset.action==='add-break'?'break':'play',minutes:el.dataset.action==='add-break'?10:15,sb:0,bb:0,ante:0,game:el.dataset.action==='add-break'?'':(editor.value.levels.slice().reverse().find(l=>l.kind==='play')?.game||''),chipUp:false});render();break;
    case 'undo-elimination':await commit({type:'undo-elimination',tournamentId:selected});break;
    case 'auto-seat':if(confirm('Shuffle and reassign seats for all remaining players?')){const order=active(current()).map(e=>e.id);for(let i=order.length-1;i>0;i--){const j=crypto.getRandomValues(new Uint32Array(1))[0]%(i+1);[order[i],order[j]]=[order[j],order[i]];}await commit({type:'auto-seat',tournamentId:selected,order});}break;
    case 'finish':if(confirm('Confirm the winner and final payouts? This locks the tournament results.'))await commit({type:'finish',tournamentId:selected});break;
    case 'fullscreen':if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('Use your browser’s full-screen option.');break;
    case 'sound':sound=!sound;if(sound)beep();render();break;
    case 'practice-demo':{
      if(mode==='cloud')throw new Error('Switch to practice mode first to create a sample tournament.');
      const eventId=id();let next=execute(state,{type:'tournament-create',id:eventId,name:'Practice tournament',date:today(),templateId:state.templates[0].id},timeNow());
      for(let i=1;i<=4;i++){let p=next.players.find(p=>p.name==='Practice Player '+i);if(!p){const pid=id();next=execute(next,{type:'player-save',id:pid,name:'Practice Player '+i});p=next.players.find(p=>p.id===pid);}next=execute(next,{type:'register',tournamentId:eventId,playerId:p.id,paid:true},timeNow());}
      state=next;localStorage.setItem(localKey,JSON.stringify(state));chooseTournament(eventId);go('manage');toast('Practice tournament ready. Try starting the clock.');break;
    }
  }
}catch(e){toast(e.message||'Something went wrong.',true);}});
function formatChipInput(input){
  const value=input.value,start=input.selectionStart??value.length,end=input.selectionEnd??start;
  if(/[^0-9,]/.test(value)){input.setCustomValidity('Enter a whole number of chips.');return;}
  const digits=value.replace(/,/g,''),normalized=digits.replace(/^0+(?=\d)/,'');
  const formatted=normalized.replace(/\B(?=(\d{3})+(?!\d))/g,',');
  input.setCustomValidity(digits&&Number.isSafeInteger(Number(digits))&&Number(digits)>0?'':'Enter a whole number of chips greater than zero.');
  if(value===formatted)return;
  const removed=digits.length-normalized.length;
  const position=offset=>{const target=Math.max(0,value.slice(0,offset).replace(/\D/g,'').length-removed);if(!target)return 0;let seen=0;for(let i=0;i<formatted.length;i++){if(/\d/.test(formatted[i])&&++seen===target)return i+1;}return formatted.length;};
  input.value=formatted;input.setSelectionRange(position(start),position(end));
}
document.addEventListener('input',event=>{if(event.target.dataset.chips)formatChipInput(event.target);if(event.target.form?.id==='player-form'&&event.target.name==='name'){const form=event.target.form,match=state.players.find(p=>p.id!==form.elements.id?.value&&normalizePlayerName(p.name)===normalizePlayerName(event.target.value));let feedback=form.querySelector('.name-feedback');if(!feedback){feedback=document.createElement('p');feedback.className='name-feedback';feedback.setAttribute('role','status');event.target.closest('label').after(feedback);}feedback.textContent=match?'That name already exists. Please choose a different name.':'';event.target.setCustomValidity(match?'That name already exists. Please choose a different name.':'');}if(['buyIn','dealerToke'].includes(event.target.name)&&$('#entry-split')){const form=event.target.form,buyIn=Math.round(Number(form.elements.buyIn.value)*100),toke=Math.round(Number(form.elements.dealerToke.value)*100);$('#entry-split').textContent=money(buyIn)+' total − '+money(toke)+' dealer toke = '+money(buyIn-toke)+' before the house percentage.';}if(event.target.id==='player-search'){playerSearch=event.target.value;$('#player-results').innerHTML=playerRows(state.players.filter(p=>(showArchived||!p.archived)&&(normalizePlayerName(p.name)+' '+p.id.toLowerCase()+' '+(p.phone||'')).includes(normalizePlayerName(playerSearch))).sort((a,b)=>a.name.localeCompare(b.name)));}if(event.target.id==='signup-search'){signupSearch=event.target.value;const t=current(),enrolled=new Set(t.entries.map(e=>e.playerId));$('#signup-results').innerHTML=registrationRows(state.players.filter(p=>!p.archived&&!enrolled.has(p.id)&&p.name.toLowerCase().includes(signupSearch.toLowerCase())).sort((a,b)=>a.name.localeCompare(b.name)),t);}});
document.addEventListener('change',event=>{if(event.target.id==='current-tournament')chooseTournament(event.target.value);if(event.target.id==='show-archived'){showArchived=event.target.checked;render();}});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,fd=new FormData(form);try{
  if(form.id==='auth-form'){
    const feedback=$('#auth-feedback');feedback.textContent='Connecting…';const method=event.submitter?.value==='signup'?'signUp':'signInWithPassword';
    const buttons=form.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);
    try{const payload={email:String(fd.get('email')),password:String(fd.get('password'))};if(method==='signUp')payload.options={emailRedirectTo:location.origin+APP_ROOT};const {data,error}=await db.auth[method](payload);if(error)throw error;
      if(data.session){session=data.session;dlg.close();await enterCloud();toast('Signed in. Open this site and use the same data account on your phone.');}
      else feedback.textContent='Check your email to confirm the account, then return here and sign in.';
    }catch(e){feedback.textContent=e.message;}finally{buttons.forEach(b=>b.disabled=false);}return;
  }
  if(form.id==='player-form'){if(await commit({type:'player-save',id:fd.get('id')||id(),name:fd.get('name'),phone:fd.get('phone'),notes:fd.get('notes')})){if(dlg.open)dlg.close();toast('Player saved.');render();}return;}
  if(form.id==='new-tournament-form'){const eventId=id();if(await commit({type:'tournament-create',id:eventId,name:fd.get('name'),date:fd.get('date'),templateId:fd.get('templateId')})){dlg.close();chooseTournament(eventId);go('signup');toast('Tournament created.');}return;}
  if(form.id==='structure-form'){
    if(mode==='cloud'&&editor.version!==version)throw new Error('Data changed on another device. Reopen this editor before saving.');captureEditor();const saved=clone(editor);
    const action=saved.event?{type:'tournament-settings',tournamentId:saved.value.id,settings:saved.value.settings,...(form.querySelector('[data-level]')?{levels:saved.value.levels}:{})}:{type:'template-save',template:saved.value};
    if(await commit(action)){editor=null;render();toast(saved.event?'Tournament settings saved.':'Structure saved.');}return;
  }
  if(form.id==='payout-form'){const s=readPayout(form,clone(current().settings));if(await commit({type:'tournament-settings',tournamentId:selected,settings:s})){toast('Payouts updated.');}return;}
  if(form.id==='payment-form'){if(await commit({type:'payment',tournamentId:selected,entryId:fd.get('entryId'),kind:fd.get('kind'),paid:fd.has('paid')})){dlg.close();toast('Payment recorded.');}return;}
  if(form.id==='seat-form'){const value=fd.get('seat'),[table,seat]=value==='unseated'?[null,null]:value.split('/').map(Number);if(await commit({type:'seat',tournamentId:selected,entryId:fd.get('entryId'),table,seat})){dlg.close();toast('Seat saved.');}return;}
}catch(e){toast(e.message,true);}});
window.addEventListener('popstate',()=>{view=new URLSearchParams(location.search).get('view')||'home';editor=null;render();});
window.addEventListener('storage',event=>{if(mode==='practice'&&event.key===localKey){state=loadPractice();if(!editor&&!dlg.open)render();}});
